window.docContents[103].resolve({"/Architecture/#architecture":{"contents":"\nL4YAML implements a two-pass pipeline that mirrors the layered\nstructure of the YAML 1.2.2 specification itself.\nInput bytes flow through a character-level scanner,\nproducing a typed token stream, which a recursive-descent parser\nconverts into a structured AST.\n\n\n\n\n\n\n\n\n\n\n\n","context":"L4YAML: A Verified YAML 1.2.2 Parser in Lean 4","header":"2. Architecture","id":"/Architecture/#architecture"},"/Verification/#verification":{"contents":"\nL4YAML employs a three-layer verification strategy that combines\nformal proofs, compile-time checks, and runtime tests to achieve\ncomprehensive coverage of the YAML 1.2.2 specification.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"L4YAML: A Verified YAML 1.2.2 Parser in Lean 4","header":"3. Verification","id":"/Verification/#verification"},"/Verification/What-L4YAML-Proves/#L4YAML___-A-Verified-YAML-1___2___2-Parser-in-Lean-4--Verification--What-L4YAML-Proves--End-to-End-Correctness--parse_complete--___-propBridge":{"contents":"4.2 — ValidYamlProp → parse .ok.  Completeness with the\nsame Prop-wrapping shape as parse_sound_shallow; an\nengineering follow-up analogous to parse_sound_deep would\nexpose the pipeline stages and cite the completeness lemmas\ndirectly.\n\n \n\n* ChainDepth: propBridge* Module: L4YAML.Proofs.EndToEndCorrectness\n\n","context":"L4YAML: A Verified YAML 1.2.2 Parser in Lean 4\u0009Verification\u0009What L4YAML Proves\u0009End-to-End Correctness","header":"3.4.4.3. parse_complete  — propBridge","id":"/Verification/What-L4YAML-Proves/#L4YAML___-A-Verified-YAML-1___2___2-Parser-in-Lean-4--Verification--What-L4YAML-Proves--End-to-End-Correctness--parse_complete--___-propBridge"}});